diff --git a/pool/context_pool.go b/pool/context_pool.go
index d1b09cc..b7a0055 100644
--- a/pool/context_pool.go
+++ b/pool/context_pool.go
@@ -5,20 +5,20 @@ import (
 )

 type ContextPool struct {
-	errPool ErrorPool
+	ErrorPool

 	ctx    context.Context
 	cancel context.CancelFunc
 }

 func (g *ContextPool) Do(f func(ctx context.Context) error) {
-	g.errPool.Do(func() error {
+	g.ErrorPool.Go(func() error {
 		err := f(g.ctx)
 		if err != nil && g.cancel != nil {
 			// Add the error directly because otherwise, canceling could cause
 			// another goroutine to exit and return an error before this error
 			// was added, which breaks the expectations of WithFirstError().
-			g.errPool.addErr(err)
+			g.ErrorPool.addErr(err)
 			g.cancel()
 			return nil
 		}
@@ -27,7 +27,7 @@ func (g *ContextPool) Do(f func(ctx context.Context) error) {
 }

 func (p *ContextPool) Wait() error {
-	return p.errPool.Wait()
+	return p.ErrorPool.Wait()
 }

 func (p *ContextPool) WithCancelOnError() *ContextPool {
@@ -36,11 +36,6 @@ func (p *ContextPool) WithCancelOnError() *ContextPool {
 }

 func (p *ContextPool) WithMaxGoroutines(limit int) *ContextPool {
-	p.errPool = *p.errPool.WithMaxGoroutines(limit)
-	return p
-}
-
-func (p *ContextPool) WithFirstError() *ContextPool {
-	p.errPool = *p.errPool.WithFirstError()
+	p.ErrorPool = *p.ErrorPool.WithMaxGoroutines(limit)
 	return p
 }
diff --git a/pool/pool.go b/pool/pool.go
index 8194373..e4ea615 100644
--- a/pool/pool.go
+++ b/pool/pool.go
@@ -53,8 +53,8 @@ func (p *Pool) WithErrors() *ErrorPool {

 func (p Pool) WithContext(ctx context.Context) *ContextPool {
 	return &ContextPool{
-		errPool: *p.WithErrors(),
-		ctx:     ctx,
+		ErrorPool: *p.WithErrors(),
+		ctx:       ctx,
 	}
 }
